    89→/* AstGen creation */
    90→AstGen *astgen_new(CirModule *m) {
    91→    AstGen *g = (AstGen *)malloc(sizeof(AstGen));
    92→    if (!g) return NULL;
    93→    g->module = m;
    94→    g->var_names = (char **)malloc(sizeof(char *) * 256);
    95→    if (!g->var_names) {
    96→        free(g);
    97→        return NULL;
    98→    }
    99→    g->var_ids = (uint32_t *)malloc(sizeof(uint32_t) * 256);
   100→    if (!g->var_ids) {
   101→        free(g->var_names);
   102→        free(g);
   103→        return NULL;
   104→    }
   105→    g->var_count = 0;
   106→    g->var_cap = 256;
   107→    g->break_label = 0;
   108→    g->continue_label = 0;
   109→    return g;
   110→}
   111→
   112→/* AstGen cleanup */
   113→void astgen_free(AstGen *g) {
   114→    if (!g) return;
   115→    if (g->var_names) free(g->var_names);
   116→    if (g->var_ids) free(g->var_ids);
   117→    free(g);
   118→}
