   130→/* Expression generation */
   131→CirRef astgen_expr(AstGen *g, Node *expr) {
   132→    if (!expr) return CIR_REF_NULL;
   133→
   134→    switch (expr->kind) {
   135→        case ND_INT_LIT: {
   136→            CirInst inst = {.op = CIR_LOAD_INT, .u.load_int.imm = expr->int_val};
   137→            return cir_emit(g->module, inst);
   138→        }
   139→        case ND_FLOAT_LIT: {
   140→            CirInst inst = {.op = CIR_LOAD_FLOAT, .u.load_float.imm = expr->float_val};
   141→            return cir_emit(g->module, inst);
   142→        }
   143→        case ND_CHAR_LIT: {
   144→            CirInst inst = {.op = CIR_LOAD_INT, .u.load_int.imm = expr->char_val};
   145→            return cir_emit(g->module, inst);
   146→        }
   147→        case ND_STR_LIT: {
   148→            uint32_t str_idx = cir_intern_str(g->module, expr->str_val);
   149→            CirInst inst = {.op = CIR_LOAD_STR, .u.load_str.str_idx = str_idx};
   150→            return cir_emit(g->module, inst);
   151→        }
   152→        case ND_IDENT: {
   153→            uint32_t name_idx = astgen_lookup_var(g, expr->name);
   154→            CirInst inst = {.op = CIR_LOAD_VAR, .u.load_var.name_idx = name_idx};
   155→            return cir_emit(g->module, inst);
   156→        }
   157→        case ND_BINARY: {
   158→            CirRef lhs = astgen_expr(g, expr->left);
   159→            CirRef rhs = astgen_expr(g, expr->right);
   160→            int op_val = 0;
   161→            switch (expr->op) {
   162→                case TK_PLUS: op_val = 0; break;
   163→                case TK_MINUS: op_val = 1; break;
   164→                case TK_STAR: op_val = 2; break;
   165→                case TK_SLASH: op_val = 3; break;
   166→                case TK_PERCENT: op_val = 4; break;
   167→                case TK_LE: op_val = 6; break;
   168→                case TK_GT: op_val = 7; break;
   169→                case TK_GE: op_val = 8; break;
   170→                case TK_EQ: op_val = 12; break;
   171→                case TK_NEQ: op_val = 13; break;
   172→                case TK_LT: op_val = 14; break;
   173→                case TK_AMPERSAND: op_val = 9; break;
   174→                case TK_PIPE: op_val = 10; break;
   175→                case TK_CARET: op_val = 11; break;
   176→                case TK_LSHIFT: op_val = 15; break;
   177→                case TK_RSHIFT: op_val = 16; break;
   178→                case TK_AND: op_val = 18; break;
   179→                case TK_OR: op_val = 19; break;
   180→                default: op_val = 0;
   181→            }
   182→            CirInst inst = {.op = CIR_BINARY, .u.binary = {.op = op_val, .lhs = lhs, .rhs = rhs}};
   183→            return cir_emit(g->module, inst);
   184→        }
   185→        case ND_ASSIGN: {
   186→            CirRef rhs = astgen_expr(g, expr->right);
   187→            if (expr->left->kind == ND_IDENT) {
   188→                uint32_t name_idx = astgen_lookup_var(g, expr->left->name);
   189→                CirInst inst = {.op = CIR_STORE_VAR, .u.store_var = {.name_idx = name_idx, .value = rhs}};
   190→                return cir_emit(g->module, inst);
   191→            }
   192→            return rhs;
   193→        }
   194→        case ND_CALL: {
   195→            CirRef callee = astgen_expr(g, expr->left);
   196→            int arg_count = expr->child_count;
   197→            CirRef *args = NULL;
   198→            if (arg_count > 0) {
   199→                args = (CirRef *)malloc(sizeof(CirRef) * arg_count);
   200→                for (int i = 0; i < arg_count; i++) {
   201→                    args[i] = astgen_expr(g, expr->children[i]);
   202→                }
   203→            }
   204→            CirInst inst = {.op = CIR_CALL, .u.call = {.callee = callee, .args = args, .arg_count = arg_count}};
   205→            return cir_emit(g->module, inst);
   206→        }
   207→        case ND_UNARY: {
   208→            CirRef operand = astgen_expr(g, expr->left);
   209→            int op_val = 0;
   210→            switch (expr->op) {
   211→                case TK_MINUS: op_val = 0; break; /* NEG */
   212→                case TK_BANG: op_val = 1; break;  /* NOT */
   213→                case TK_TILDE: op_val = 2; break; /* BITNOT */
   214→                default: op_val = 0;
   215→            }
   216→            CirInst inst = {.op = CIR_UNARY, .u.unary = {.op = op_val, .operand = operand}};
   217→            return cir_emit(g->module, inst);
   218→        }
   219→        case ND_INDEX: {
   220→            CirRef array = astgen_expr(g, expr->left);
   221→            CirRef idx = astgen_expr(g, expr->right);
   222→            CirInst inst = {.op = CIR_INDEX, .u.index = {.array = array, .idx = idx}};
   223→            return cir_emit(g->module, inst);
   224→        }
   225→        case ND_MEMBER: {
   226→            CirRef object = astgen_expr(g, expr->left);
   227→            CirInst inst = {.op = CIR_MEMBER, .u.member = {.object = object, .field_idx = expr->member_idx}};
   228→            return cir_emit(g->module, inst);
   229→        }
   230→        case ND_ARROW: {
   231→            CirRef ptr = astgen_expr(g, expr->left);
   232→            CirRef deref_inst = cir_emit(g->module, (CirInst){.op = CIR_DEREF, .u.deref.operand = ptr});
   233→            CirInst member_inst = {.op = CIR_MEMBER, .u.member = {.object = deref_inst, .field_idx = expr->member_idx}};
   234→            return cir_emit(g->module, member_inst);
   235→        }
   236→        default:
   237→            return CIR_REF_NULL;
   238→    }
   239→}
