   396→/* Debug output */
   397→static const char *cir_opcode_to_string(CirOpcode op) {
   398→    switch (op) {
   399→        case CIR_LOAD_INT: return "LOAD_INT";
   400→        case CIR_LOAD_FLOAT: return "LOAD_FLOAT";
   401→        case CIR_LOAD_STR: return "LOAD_STR";
   402→        case CIR_LOAD_VAR: return "LOAD_VAR";
   403→        case CIR_STORE_VAR: return "STORE_VAR";
   404→        case CIR_ADDR_OF: return "ADDR_OF";
   405→        case CIR_DEREF: return "DEREF";
   406→        case CIR_INDEX: return "INDEX";
   407→        case CIR_MEMBER: return "MEMBER";
   408→        case CIR_BINARY: return "BINARY";
   409→        case CIR_UNARY: return "UNARY";
   410→        case CIR_LABEL: return "LABEL";
   411→        case CIR_JMP: return "JMP";
   412→        case CIR_JMP_IF: return "JMP_IF";
   413→        case CIR_RETURN: return "RETURN";
   414→        case CIR_FUNC_BEGIN: return "FUNC_BEGIN";
   415→        case CIR_FUNC_END: return "FUNC_END";
   416→        case CIR_CALL: return "CALL";
   417→        case CIR_ARG: return "ARG";
   418→        case CIR_NOP: return "NOP";
   419→        default: return "UNKNOWN";
   420→    }
   421→}
