   423→void cir_module_dump(CirModule *m) {
   424→    if (!m) return;
   425→    printf("=== CIR Module ===\n");
   426→    printf("Instructions: %u, Strings: %u\n", m->inst_count, m->str_count);
   427→    printf("\nInstructions:\n");
