     8→/* CIR Reference (index into instruction array) */
     9→typedef uint32_t CirRef;
    10→#define CIR_REF_NULL 0
    11→
    12→/* CIR Opcodes (30개) */
    13→typedef enum {
    14→    /* Literal loads */
    15→    CIR_LOAD_INT,
    16→    CIR_LOAD_FLOAT,
    17→    CIR_LOAD_STR,
    18→    CIR_LOAD_VAR,
    19→
    20→    /* Memory operations */
    21→    CIR_STORE_VAR,
    22→    CIR_ADDR_OF,
    23→    CIR_DEREF,
    24→    CIR_INDEX,
    25→    CIR_MEMBER,
    26→
    27→    /* Arithmetic/Logic */
    28→    CIR_BINARY,
    29→    CIR_UNARY,
    30→    CIR_CAST,
    31→
    32→    /* Control flow */
    33→    CIR_LABEL,
    34→    CIR_JMP,
    35→    CIR_JMP_IF,
    36→    CIR_RETURN,
    37→
    38→    /* Functions */
    39→    CIR_FUNC_BEGIN,
    40→    CIR_FUNC_END,
    41→    CIR_CALL,
    42→    CIR_ARG,
    43→
    44→    /* Special */
    45→    CIR_SIZEOF,
    46→    CIR_PHI,
    47→    CIR_NOP,
    48→} CirOpcode;
    49→
    50→/* Individual instruction */
    51→typedef struct {
    52→    CirOpcode op;
    53→    union {
    54→        struct { long long imm; }                              load_int;
    55→        struct { double imm; }                                 load_float;
